CREATE TABLE IF NOT EXISTS study_files (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT DEFAULT '',object_key TEXT NOT NULL UNIQUE,original_name TEXT NOT NULL,content_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS study_file_chunks(file_id TEXT NOT NULL,chunk_index INTEGER NOT NULL,data BLOB NOT NULL,PRIMARY KEY(file_id,chunk_index),FOREIGN KEY(file_id) REFERENCES study_files(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_study_file_chunks_file ON study_file_chunks(file_id,chunk_index);
CREATE TABLE IF NOT EXISTS quizzes (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT DEFAULT '',published INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quiz_questions (id TEXT PRIMARY KEY,quiz_id TEXT NOT NULL,question TEXT NOT NULL,options_json TEXT NOT NULL,correct_index INTEGER NOT NULL,position INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quiz_attempts (id TEXT PRIMARY KEY,quiz_id TEXT NOT NULL,user_id TEXT NOT NULL,score INTEGER NOT NULL,total INTEGER NOT NULL,answers_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(quiz_id) REFERENCES quizzes(id));
CREATE INDEX IF NOT EXISTS idx_quiz_attempts_user ON quiz_attempts(user_id,created_at);
CREATE TABLE IF NOT EXISTS dashboard_rows (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,subject TEXT NOT NULL,goal TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_dashboard_rows_user ON dashboard_rows(user_id,created_at);